import reactor.core.publisher.Flux;
import reactor.core.publisher.Mono;
import java.util.List;

public class ReactiveTypeGuard {

    // WRONG: Cannot create arrays of generic types
    // Mono<String>[] invalidArray = new Mono[10]; 

    public <T> void processPayload(Object payload, Class<T> targetType) {
        // WRONG: Cannot use instanceof with parameterized types (payload instanceof Mono<T>)

        if (payload instanceof Mono) {
            // CORRECT: Use Class tokens or Spring's ResolvableType for runtime introspection
            ((Mono<?>) payload).subscribe(item -> {
                if (targetType.isInstance(item)) {
                    System.out.println("Successfully processed: " + item);
                }
            });
        }
    }
}
